<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="theme-color" content="#f4f6f7">
    <meta name="turbo-cache-control" content="no-cache">
    <title>Payment operations | Parcel Claims</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css" referrerpolicy="no-referrer">
    <script src="https://cdn.jsdelivr.net/npm/@hotwired/turbo@8.0.23/dist/turbo.es2017-umd.js" defer></script>
    <style>
        :root{--ink:#1b2d3a;--muted:#72818b;--line:#e3e8eb;--paper:#f4f6f7;--white:#fff;--nav:#123e54;--nav-deep:#0d3043;--blue:#17617d;--blue-soft:#eaf2f5;--green:#2f705a;--green-soft:#eaf4ef;--amber:#9c6820;--amber-soft:#fbf2df;--red:#a3443d;--red-soft:#fff1ef;--shadow:0 8px 24px #233c4b0a}
        *{box-sizing:border-box}
        body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:14px;-webkit-font-smoothing:antialiased}
        button,input,select{font:inherit}
        button,a{-webkit-tap-highlight-color:transparent}
        a{color:inherit;text-decoration:none}
        .layout{min-height:100vh}
        .sidebar{position:fixed;z-index:30;inset:0 auto 0 0;display:flex;width:248px;flex-direction:column;background:linear-gradient(180deg,#123e54,#10364a);color:#e7f0f3}
        .brand{display:flex;align-items:center;gap:12px;height:76px;padding:0 23px;border-bottom:1px solid #ffffff19}
        .brand-icon{display:grid;place-items:center;width:35px;height:35px;border-radius:8px;background:#ffffff16;color:#fff}
        .brand-title{font-size:12px;font-weight:750;letter-spacing:.08em;text-transform:uppercase}
        .brand-title small{display:block;margin-top:4px;color:#a9c0ca;font-size:9px;font-weight:600;letter-spacing:.15em}
        .side-label{margin:27px 20px 11px;color:#90acb9;font-size:9px;font-weight:750;letter-spacing:.16em;text-transform:uppercase}
        .side-nav{display:grid;gap:4px;padding:0 12px}
        .side-nav a{display:flex;align-items:center;gap:12px;min-height:42px;padding:0 12px;border-radius:5px;color:#c5d5dc;font-size:12px;font-weight:550;transition:background .15s,color .15s}
        .side-nav a i{width:17px;text-align:center;color:#a8c2ce;font-size:13px}
        .side-nav a:hover,.side-nav a.active{background:#ffffff15;color:#fff}
        .side-nav a.active{box-shadow:inset 2px 0 #e2a16e}
        .side-nav a.active i{color:#efb58c}
        .sidebar-bottom{margin-top:auto;padding:17px 14px;border-top:1px solid #ffffff19}
        .gateway{display:flex;align-items:center;gap:10px;padding:11px 10px;border-radius:5px;background:#ffffff0c}
        .gateway-dot{width:7px;height:7px;border-radius:50%;background:#74c29a;box-shadow:0 0 0 3px #74c29a20}
        .gateway strong{display:block;font-size:10px}.gateway small{display:block;margin-top:3px;color:#abc0c8;font-size:9px}
        .main-shell{min-height:100vh;margin-left:248px}
        .topbar{position:sticky;z-index:15;top:0;display:flex;align-items:center;justify-content:space-between;height:76px;padding:0 34px;border-bottom:1px solid var(--line);background:#ffffffed;backdrop-filter:blur(12px)}
        .crumb{color:#8a969c;font-size:11px}.crumb strong{color:#354b58;font-weight:650}
        .topbar-right{display:flex;align-items:center;gap:17px}.secure-tag{display:flex;align-items:center;gap:7px;color:#627680;font-size:10px}.secure-tag i{color:var(--green)}
        .top-divider{width:1px;height:26px;background:var(--line)}.profile{display:flex;align-items:center;gap:10px}
        .avatar{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#e9eff2;color:var(--nav);font-size:12px;font-weight:750}
        .profile-copy strong{display:block;font-size:10px}.profile-copy small{display:block;margin-top:3px;color:#839097;font-size:9px}
        .logout{margin-left:5px;padding:8px 10px;border:0;background:transparent;color:#6e7b83;font-size:11px;cursor:pointer}.logout:hover{color:var(--red)}
        .mobile-menu{display:none;border:0;background:none;color:var(--nav);font-size:18px}
        .content{max-width:1470px;margin:auto;padding:29px 34px 56px}
        .page-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:24px}
        .eyebrow{margin:0 0 7px;color:#9b633e;font-size:9px;font-weight:750;letter-spacing:.17em;text-transform:uppercase}
        .page-heading h1{margin:0;font-size:23px;font-weight:700;letter-spacing:-.035em}.page-heading p:last-child{margin:7px 0 0;color:#78868e;font-size:11px}
        .primary{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:39px;padding:0 14px;border:1px solid var(--blue);border-radius:4px;background:var(--blue);color:#fff;font-size:11px;font-weight:700;cursor:pointer;transition:background .15s}.primary:hover{background:var(--nav-deep)}
        .secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:33px;padding:0 10px;border:1px solid #d3dfe3;border-radius:4px;background:#fff;color:var(--blue);font-size:10px;font-weight:650;cursor:pointer}.secondary:hover{background:#f2f7f8}
        .alert{display:flex;align-items:center;gap:9px;margin-bottom:18px;padding:12px 14px;border:1px solid #cce2d5;border-radius:4px;background:var(--green-soft);color:#315f4d;font-size:11px}.alert.error{border-color:#f0d2ce;background:var(--red-soft);color:var(--red)}
        .copy-field{display:flex;flex:1;min-width:180px}.copy-field input{width:100%;min-width:0;padding:9px 11px;border:1px solid #cfdcdd;border-radius:4px 0 0 4px;background:white;color:var(--ink);font-size:11px}.copy-field button{padding:0 12px;border:1px solid var(--blue);border-radius:0 4px 4px 0;background:var(--blue);color:#fff;font-size:10px;font-weight:650;cursor:pointer}
        .metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:25px}.metric{position:relative;overflow:hidden;min-height:103px;padding:17px 18px;border:1px solid var(--line);border-radius:5px;background:#fff;box-shadow:var(--shadow)}
        .metric-top{display:flex;align-items:center;justify-content:space-between;color:#73818a;font-size:10px;font-weight:550}.metric-icon{display:grid;place-items:center;width:29px;height:29px;border-radius:5px;background:var(--blue-soft);color:var(--blue);font-size:12px}.metric-value{display:block;margin-top:12px;font-size:22px;font-weight:700;letter-spacing:-.04em}.metric-note{margin-left:7px;color:#87939a;font-size:9px;font-weight:500;letter-spacing:0}
        .panel{overflow:hidden;border:1px solid var(--line);border-radius:5px;background:#fff;box-shadow:var(--shadow)}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:17px 19px;border-bottom:1px solid var(--line)}
        .panel-title h2{margin:0;font-size:13px;font-weight:700}.panel-title p{margin:5px 0 0;color:#87939a;font-size:10px}.tools{display:flex;align-items:center;gap:8px}
        .search{position:relative}.search i{position:absolute;top:50%;left:11px;transform:translateY(-50%);color:#829098;font-size:10px}.search input{width:205px;height:34px;padding:0 11px 0 30px;border:1px solid #d8e0e3;border-radius:4px;outline:none;font-size:10px}.search input:focus,.filter:focus{border-color:#76a3b4;box-shadow:0 0 0 3px #17617d12}
        .filter{height:34px;padding:0 25px 0 10px;border:1px solid #d8e0e3;border-radius:4px;background:#fff;color:#50636e;font-size:10px;outline:none}.claim-list{display:grid;gap:0}.claim-item{padding:18px 19px;border-bottom:1px solid #edf0f1}.claim-item:last-child{border-bottom:0}
        .claim-main{display:grid;grid-template-columns:minmax(200px,1.1fr) minmax(170px,.8fr) minmax(205px,1fr) auto;align-items:center;gap:15px}
        .customer{display:flex;align-items:center;gap:11px;min-width:0}.customer-avatar{display:grid;place-items:center;width:36px;height:36px;flex:0 0 auto;border-radius:50%;background:#eaf1f3;color:#2f667d;font-size:11px;font-weight:750}
        .customer-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;font-weight:700}.customer-email{overflow:hidden;margin-top:4px;color:#7c8990;font-size:10px;text-overflow:ellipsis;white-space:nowrap}
        .ref-label{color:#93a0a5;font-size:9px;text-transform:uppercase;letter-spacing:.08em}.ref-value{margin-top:5px;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:10px;color:#475b66}
        .status{display:inline-flex;align-items:center;gap:6px;width:max-content;padding:6px 8px;border-radius:3px;font-size:9px;font-weight:700}.status:before{width:6px;height:6px;border-radius:50%;background:currentColor;content:""}.status.verified{background:var(--green-soft);color:var(--green)}.status.pending{background:var(--amber-soft);color:var(--amber)}.status.other{background:#eef1f3;color:#697880}
        .claim-actions{display:flex;justify-content:flex-end;gap:7px}.detail-toggle{margin-top:14px;padding:0;border:0;background:none;color:#637782;font-size:10px;font-weight:650;cursor:pointer}.detail-toggle i{margin-right:5px;color:#6f8995}
        .claim-details{display:grid;grid-template-columns:1.2fr 1fr;gap:22px;margin:14px 0 0 47px;padding:15px 17px;border:1px solid #e9edef;border-radius:4px;background:#f9faf9}.detail-section h3{margin:0 0 10px;color:#65757d;font-size:9px;font-weight:750;letter-spacing:.11em;text-transform:uppercase}
        .card-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid #e9edef}.card-row:first-of-type{padding-top:0;border-top:0}.card-info{display:flex;align-items:center;gap:10px}.card-brand{display:grid;place-items:center;width:31px;height:25px;border:1px solid #e2e7e9;border-radius:3px;background:#fff;color:#536c78;font-size:12px}.card-title{font-size:10px;font-weight:700}.card-meta{margin-top:4px;color:#829097;font-size:9px}.tag{display:inline-block;margin-left:5px;padding:3px 5px;border-radius:3px;background:#e9f3ed;color:var(--green);font-size:8px;font-weight:700}.muted{color:#8a969c;font-size:10px}
        .tx-row{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:9px;padding:7px 0;border-top:1px solid #e9edef;font-size:9px}.tx-row:first-of-type{border-top:0;padding-top:0}.tx-name{overflow:hidden;color:#556973;text-overflow:ellipsis;white-space:nowrap}.tx-amount{font-weight:700}.tx-status{color:#75858b}.tx-actions{display:flex;align-items:center;gap:5px}.tx-button{padding:4px 6px;border:1px solid #d5e0e2;border-radius:3px;background:#fff;color:#386a7d;font-size:8px;font-weight:650;cursor:pointer}.tx-button:hover{background:#edf4f5}
        .empty{padding:48px 20px;text-align:center}.empty-icon{display:grid;place-items:center;width:46px;height:46px;margin:0 auto 13px;border-radius:50%;background:#edf3f4;color:#567c8a;font-size:17px}.empty h3{margin:0;font-size:12px}.empty p{max-width:360px;margin:7px auto 16px;color:#7c8990;font-size:10px;line-height:1.6}
        .modal{width:min(440px,calc(100% - 28px));padding:0;border:1px solid #dfe5e7;border-radius:6px;background:#fff;color:var(--ink);box-shadow:0 22px 80px #102c3d3d}.modal::backdrop{background:#102b3bb8;backdrop-filter:blur(2px)}.modal-head{display:flex;align-items:flex-start;justify-content:space-between;padding:19px 21px;border-bottom:1px solid var(--line)}.modal-head h2{margin:0;font-size:14px}.modal-head p{margin:5px 0 0;color:#7f8b91;font-size:10px;line-height:1.5}.modal-close{border:0;background:none;color:#718088;font-size:15px;cursor:pointer}.modal-body{display:grid;gap:14px;padding:20px 21px}.modal-field label{display:block;margin-bottom:6px;font-size:10px;font-weight:700}.modal-field input{width:100%;height:38px;padding:0 10px;border:1px solid #d3dcdf;border-radius:4px;outline:none;font-size:11px}.modal-field input:focus{border-color:#76a3b4;box-shadow:0 0 0 3px #17617d12}.modal-actions{display:flex;justify-content:flex-end;gap:8px;padding:0 21px 20px}.cancel{min-height:36px;padding:0 12px;border:1px solid #d7e0e2;border-radius:4px;background:#fff;color:#5e7079;font-size:10px;font-weight:650;cursor:pointer}.danger{background:#a3443d;border-color:#a3443d}.danger:hover{background:#873833}
        .page-modal{width:min(700px,calc(100% - 28px));max-height:min(90dvh,850px);overflow:auto}.page-modal[open]{display:block}.page-modal>.panel{border:0;border-radius:0;box-shadow:none}.page-modal-back{position:sticky;top:0;z-index:2;display:block;padding:12px 18px;border-bottom:1px solid var(--line);background:#fff;color:var(--blue);font-size:11px;font-weight:700}.page-modal-back i{margin-right:6px}.page-modal .panel-head{padding:15px 18px}.page-modal .modal-body{padding:17px 18px}.page-modal .form-actions{margin-top:14px}
        .backdrop{display:none}.mobile-brand{display:none}
        turbo-frame#admin-content{display:block;min-height:100vh}
        .table-wrap{width:100%;overflow:auto}.data-table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap}.data-table th{padding:12px 17px;background:#f7f9f9;color:#849197;font-size:9px;font-weight:750;letter-spacing:.1em;text-transform:uppercase}.data-table td{padding:14px 17px;border-top:1px solid #edf0f1;color:#52646d;font-size:10px}.data-table td strong,.data-table td small{display:block}.data-table td strong{color:#304550;font-size:10px}.data-table td small{margin-top:5px;color:#839097;font-size:9px}.data-table code{color:#526a75;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:9px}.data-table tr:hover td{background:#fbfcfc}
        .admin-links{margin-top:28px}.admin-links .side-label{margin-top:0}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.form-field label{display:block;margin-bottom:7px;color:#415760;font-size:10px;font-weight:700}.form-field input,.form-field select{width:100%;height:40px;padding:0 11px;border:1px solid #d4dfe1;border-radius:4px;background:#fff;color:var(--ink);outline:none;font-size:11px}.form-field input:focus,.form-field select:focus{border-color:#76a3b4;box-shadow:0 0 0 3px #17617d12}.form-field small{display:block;margin-top:5px;color:#859299;font-size:9px}.form-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:21px;padding-top:16px;border-top:1px solid var(--line)}.form-actions-end{display:flex;justify-content:flex-end;gap:8px}.danger-outline{min-height:36px;padding:0 12px;border:1px solid #e7c5c1;border-radius:4px;background:#fff;color:var(--red);font-size:10px;font-weight:700;cursor:pointer}.check-field{display:flex;align-items:flex-start;gap:9px;color:#50656f;font-size:10px;line-height:1.6}.check-field input{margin-top:2px;accent-color:var(--blue)}.bulk-controls{display:flex;align-items:center;gap:8px;padding:11px 18px;border-bottom:1px solid var(--line);background:#f9fbfb}.bulk-controls select{height:31px;padding:0 8px;border:1px solid #d8e0e3;border-radius:4px;background:#fff;font-size:10px}.bulk-controls button{height:31px}.claim-select{display:flex;align-items:center}.claim-select input{accent-color:var(--blue)}.row-actions{display:flex;align-items:center;gap:7px}.row-link{color:var(--blue);font-size:9px;font-weight:700}.inline-delete{display:inline}.inline-delete button{padding:0;border:0;background:transparent;color:var(--red);font-size:9px;cursor:pointer}
        .heading-actions{position:relative;z-index:1;display:flex;align-items:center;gap:9px}.heading-secondary{min-height:42px;border-color:#ffffff55;background:#ffffff12;color:#fff}.heading-secondary:hover{background:#ffffff24}.share-panel{display:grid;gap:15px;margin:0 0 20px;padding:18px 20px;border:1px solid #cfe2d8;border-radius:7px;background:linear-gradient(120deg,#f3faf6,#fff)}.share-copy{display:flex;align-items:center;gap:12px}.share-icon{display:grid;place-items:center;width:39px;height:39px;flex:none;border-radius:50%;background:#dfefe5;color:#36775a}.share-copy strong{font-size:13px;color:#244d3c}.share-copy p{margin:4px 0 0;color:#657b70;font-size:11px;line-height:1.5}.share-controls{display:flex;align-items:center;gap:8px;padding-left:51px}.share-controls .copy-field{min-width:220px}.share-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:36px;padding:0 12px;border:1px solid #d2e0d9;border-radius:4px;background:#fff;color:#3e6251;font-size:10px;font-weight:650}.share-button:hover{background:#f5faf7}.share-button.whatsapp{border-color:#b9ddc8;color:#25824f}.share-inline{display:flex;gap:16px;margin-top:9px}.share-inline a{color:var(--blue);font-size:10px;font-weight:650}.share-inline i{margin-right:5px}.detail-section>.copy-field{max-width:640px;margin-top:8px}.share-panel .copy-field button{white-space:nowrap}.billing-subscriptions{margin-top:20px}.full-field{grid-column:1/-1}.form-field textarea{width:100%;padding:10px;border:1px solid #d8e0e3;border-radius:4px;background:#fff;color:var(--ink);font:inherit;font-size:11px;resize:vertical}.form-field textarea:focus{border-color:#91adb9;outline:none;box-shadow:0 0 0 2px #17617d12}.input-suffix{display:flex;align-items:center}.input-suffix input{min-width:0;flex:1;border-radius:4px 0 0 4px}.input-suffix span{display:grid;place-items:center;align-self:stretch;padding:0 11px;border:1px solid #d8e0e3;border-left:0;border-radius:0 4px 4px 0;background:#f6f8f9;color:#607782;font-size:10px;font-weight:700}.consent-check{margin-top:13px;padding:12px;border:1px solid #e4eaec;border-radius:4px;background:#f8fafb}.billing-detail-row td{padding:10px 16px!important;background:#fafcfc;border-bottom:1px solid var(--line)!important}.billing-detail-row details summary{color:var(--blue);font-size:10px;font-weight:700;cursor:pointer}.consent-record{margin:10px 0;padding:10px;border-left:2px solid #6b9b87;background:#f1f6f3;color:#50665b;font-size:10px}.consent-record p{margin:5px 0 0;line-height:1.5}.billing-attempt{display:grid;grid-template-columns:180px 90px minmax(180px,1fr);gap:10px;align-items:start;padding:8px 0;border-top:1px solid #ebeff0;color:#65767e;font-size:9px}.billing-attempt small{display:block;margin-top:4px;color:var(--red)}
        [hidden]{display:none!important}
        .page-heading{position:relative;overflow:hidden;align-items:center;min-height:135px;margin-bottom:21px;padding:25px 27px;border-radius:7px;background:linear-gradient(112deg,#103b52 0%,#165e72 100%);box-shadow:0 12px 26px #123e541b;color:#fff}.page-heading:after{position:absolute;right:145px;top:-95px;width:260px;height:260px;border:1px solid #ffffff20;border-radius:50%;box-shadow:0 0 0 28px #ffffff0d,0 0 0 60px #ffffff08;content:"";pointer-events:none}.page-heading>div,.page-heading>.primary{position:relative;z-index:1}.page-heading .eyebrow{color:#f0bd91}.page-heading h1{font-size:27px;letter-spacing:-.045em}.page-heading p:last-child{color:#d2e2e7}.page-heading>.primary{min-height:42px;border-color:#fff;background:#fff;color:#16465d}.page-heading>.primary:hover{background:#eaf2f4}.metric{min-height:116px;border-color:#e5eaec;border-top-width:3px;border-top-color:#8ca9b5;background:linear-gradient(145deg,#fff 55%,#f8fafb);box-shadow:0 7px 18px #233c4b0b}.metric:nth-child(1){border-top-color:#26758c}.metric:nth-child(2){border-top-color:#4b9879}.metric:nth-child(3){border-top-color:#6e75b7}.metric:nth-child(4){border-top-color:#d58c50}.metric:nth-child(1) .metric-icon{background:#e4f1f4;color:#26758c}.metric:nth-child(2) .metric-icon{background:#e7f3ed;color:#3f896a}.metric:nth-child(3) .metric-icon{background:#edecf8;color:#666bac}.metric:nth-child(4) .metric-icon{background:#fbefe2;color:#bb7540}.metric-value{font-size:25px}.panel{border-radius:7px;box-shadow:0 7px 22px #233c4b0a}.panel-head{padding:19px 21px;background:linear-gradient(180deg,#fff,#fbfcfc)}.panel-title h2{font-size:14px}.claim-item{padding-top:19px;padding-bottom:19px;transition:background .15s}.claim-item:hover{background:#fbfcfc}.customer-avatar{background:linear-gradient(140deg,#eaf2f5,#ddebef);color:#1c6178}.status{padding:6px 9px;border-radius:20px}.claim-details{background:linear-gradient(145deg,#f9fbfb,#f4f7f7);border-radius:6px}.primary,.secondary,.tx-button,.cancel{transition:tran