    <dialog class="modal" id="link-dialog"><form method="post" data-turbo-frame="admin-content" action="{{ route('admin.links.create') }}">@csrf<div class="modal-head"><span><h2>Create and share form link</h2><p>Make a private customer form and share it by email or WhatsApp.</p></span><button class="modal-close" type="button" data-close-dialog aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body"><div class="modal-field"><label for="link-reference">Parcel / claim reference</label><input id="link-reference" name="claim_reference" required maxlength="100" placeholder="e.g. CLM-20481"></div><div class="modal-field"><label for="link-email">Email recipient <span class="muted">(optional)</span></label><input id="link-email" name="email" type="email" placeholder="customer@example.com"></div><div class="modal-field"><label for="link-phone">WhatsApp number <span class="muted">(optional)</span></label><input id="link-phone" name="phone" type="tel" autocomplete="tel" placeholder="Include country code, e.g. +254712345678"><small>Enter the number with its country code to address the WhatsApp share.</small></div><p class="muted">The customer enters their name, email, and card details on the secure form. Email and WhatsApp open a ready-to-send message for you.</p></div><div class="modal-actions"><button class="cancel" type="button" data-close-dialog>Cancel</button><button class="primary" type="submit"><i class="fa-solid fa-link"></i> Create form link</button></div></form></dialog>
