    <dialog class="modal" id="refund-dialog"><form method="post" data-turbo-frame="admin-content" id="refund-form" data-url-template="{{ route('admin.transactions.refund', ['transaction' => '__TRANSACTION__']) }}">@csrf<div class="modal-head"><span><h2>Issue refund</h2><p>Send a full or partial refund for this successful charge.</p></span><button class="modal-close" type="button" data-close-dialog aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body"><div class="modal-field"><label for="refund-amount">Refund amount (leave blank for full refund)</label><input id="refund-amount" name="amount" type="number" min="0.01" step="0.01" placeholder="Full amount"></div><p class="muted" id="refund-limit"></p></div><div class="modal-actions"><button class="cancel" type="button" data-close-dialog>Cancel</button><button class="primary danger" type="submit"><i class="fa-solid fa-rotate-left"></i> Confirm refund</button></div></form></dialog>

    <script>
        document.querySelectorAll('.data-table').forEach(table => {
            const labels = Array.from(table.querySelectorAll('thead th')).map(cell => cell.textContent.trim());
            table.querySelectorAll('tbody tr').forEach(row => row.querySelectorAll('td').forEach((cell, index) => {
                if (!cell.hasAttribute('colspan')) cell.dataset.label = labels[index] || '';
            }));
        });

        // Redirect links created by the previous anchor-based sidebar to the dedicated claims page.
        if (window.location.hash === '#claims') {
            window.location.replace(@json(route('admin.claims')));
        }

        const sidebar = document.getElementById('sidebar');
        const backdrop = document.getElementById('sidebar-backdrop');
        document.getElementById('menu-toggle')?.addEventListener('click', () => { sidebar.classList.toggle('open'); backdrop.classList.toggle('show'); });
        backdrop.addEventListener('click', () => { sidebar.classList.remove('open'); backdrop.classList.remove('show'); });
        document.addEventListener('turbo:frame-load', event => {
            const frame = event.target;
            if (frame.id !== 'admin-content') return;
            frame.querySelectorAll('dialog[data-auto-open]').forEach(dialog => { if (!dialog.open) dialog.showModal(); });
            frame.querySelectorAll('.data-table').forEach(table => {
                const labels = Array.from(table.querySelectorAll('thead th')).map(cell => cell.textContent.trim());
                table.querySelectorAll('tbody tr').forEach(row => row.querySelectorAll('td').forEach((cell, index) => {
                    if (!cell.hasAttribute('colspan')) cell.dataset.label = labels[index] || '';
                }));
            });
            sidebar.classList.remove('open'); backdrop.classList.remove('show');
        });
        document.addEventListener('DOMContentLoaded', () => document.querySelectorAll('dialog[data-auto-open]').forEach(dialog => { if (!dialog.open) dialog.showModal(); }));

        document.addEventListener('click', event => {
            const open = event.target.closest('[data-open-dialog]');
            if (open) document.getElementById(open.dataset.openDialog)?.showModal();
            const close = event.target.closest('[data-close-dialog]');
            if (close) close.closest('dialog')?.close();
            const toggle = event.target.closest('.detail-toggle');
            if (toggle) {
                const details = toggle.closest('.claim-item').querySelector('.claim-details');
                const expanded = toggle.getAttribute('aria-expanded') === 'true';
                toggle.setAttribute('aria-expanded', String(!expanded)); details.hidden = expanded;
                toggle.querySelector('i').className = expanded ? 'fa-solid fa-chevron-down' : 'fa-solid fa-chevron-up';
                toggle.querySelector('span').textContent = expanded ? 'Details' : 'Hide';
            }
            const charge = event.target.closest('.charge-open');
            if (charge) {
                const form = document.getElementById('charge-form'); form.action = form.dataset.urlTemplate.replace('__CARD__', charge.dataset.cardId);
                document.getElementById('charge-customer').textContent = 'Charge a saved card for ' + charge.dataset.customer + '.';
                document.getElementById('charge-dialog').showModal();
            }
            const refund = event.target.closest('.refund-open');
            if (refund) {
                const form = document.getElementById('refund-form'); form.action = form.dataset.urlTemplate.replace('__TRANSACTION__', refund.dataset.transactionId);
                const amount = document.getElementById('refund-amount'); amount.max = refund.dataset.amount; amount.value = '';
                document.getElementById('refund-limit').textContent = 'Maximum refund: ' + refund.dataset.amount;
                document.getElementById('refund-dialog').showModal();
            }
            const copyButton = event.target.closest('.copy-value');
            if (copyButton) copyText(copyButton.closest('.copy-field').querySelector('input').value, copyButton);
        });

        const search = document.getElementById('claim-search');
        const filter = document.getElementById('status-filter');
        const updateClaims = () => {
            if (!search || !filter) return;
            const term = search.value.toLowerCase().trim(); let visible = 0;
            document.querySelectorAll('.claim-item').forEach(item => {
                const matches = item.dataset.search.includes(term) && (filter.value === 'all' || item.dataset.status === filter.value);
                item.hidden = !matches; if (matches) visible++;
            });
            const noResults = document.getElementById('no-results');
            if (noResults) noResults.hidden = visible !== 0;
        };
        search?.addEventListener('input', updateClaims); filter?.addEventListener('change', updateClaims);
        document.addEventListener('turbo:frame-load', () => {
            const frameSearch = document.getElementById('claim-search'), frameFilter = document.getElementById('status-filter');
            if (!frameSearch || !frameFilter) return;
            const refresh = () => {
                const term = frameSearch.value.toLowerCase().trim(); let visible = 0;
                document.querySelectorAll('.claim-item').forEach(item => { const matches = item.dataset.search.includes(term) && (frameFilter.value === 'all' || item.dataset.status === frameFilter.value); item.hidden = !matches; if (matches) visible++; });
                const empty = document.getElementById('no-results'); if (empty) empty.hidden = visible !== 0;
            };
            frameSearch.addEventListener('input', refresh); frameFilter.addEventListener('change', refresh);
        });

        const copyText = async (value, button) => {
            try {
                if (navigator.clipboard && window.isSecureContext) await navigator.clipboard.writeText(value);
                else { const field=document.createElement('textarea');field.value=value;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();if(!document.execCommand('copy'))throw new Error('Copy was blocked');field.remove(); }
                const original=button.innerHTML;button.innerHTML='<i class="fa-solid fa-check"></i> Copied';button.classList.add('copied');window.setTimeout(()=>{button.innerHTML=original;button.classList.remove('copied')},1800);
            } catch { button.innerHTML='<i class="fa-solid fa-triangle-exclamation"></i> Select and copy'; }
        };
        document.addEventListener('click', event => { if (event.target.closest('#copy-link')) copyText(document.getElementById('generated-link').value, event.target.closest('#copy-link')); });
    </script>
